FUNCTION_BLOCK FB_S13
VAR_INPUT
    LineRun : BOOL;
    PartAtMerge : BOOL;
    PartOnMain : BOOL;
    JamSensor : BOOL;
    ResetBtn : BOOL;
    ModeAuto : BOOL;
END_VAR
VAR_OUTPUT
    MainMotor : BOOL := FALSE;
    MergeMotor : BOOL := FALSE;
    SpeedHigh : BOOL := FALSE;
    JamAlarm : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    LineRunLast : BOOL := FALSE;
    ResetBtnLast : BOOL := FALSE;
    LineRunRise : BOOL := FALSE;
    ResetBtnRise : BOOL := FALSE;
    ResetAccepted : BOOL := FALSE;
    JamCount : UINT := UINT#0;
    PartPresentCount : UINT := UINT#0;
    PartAbsentCount : UINT := UINT#0;
END_VAR

(*
需求原文：
两段输送线在合流点汇合，控制系统要同时管住
「不撞料」「不堵料」「不频繁换档」三件事。

1. LineRun = FALSE 时 MainMotor、MergeMotor 立即 FALSE，
   SpeedHigh = FALSE，Status = 16#0000。
2. 启动：LineRun 上升沿且 JamAlarm = FALSE 时 MainMotor = TRUE；
   MergeMotor 只在 PartAtMerge = FALSE 且 MainMotor = TRUE 时才允许为 TRUE。
3. 防撞互锁：PartAtMerge = TRUE 时 MergeMotor 必须为 FALSE。
4. 堵料：JamSensor = TRUE 连续 2 s（100 个扫描周期）
   → 两电机 FALSE、JamAlarm = TRUE、Status = 16#8C01。
5. 复位：JamSensor = FALSE 且 ResetBtn 上升沿才清 JamAlarm 与 Status；
   复位后必须重新给 LineRun 上升沿才允许启动。
6. 速度档：MainMotor = TRUE 且 PartOnMain 连续 TRUE 3 s（150 周期）
   → SpeedHigh = TRUE；PartOnMain 连续 FALSE 5 s（250 周期）
   → SpeedHigh = FALSE；两个时限之间保持原档位。
7. ModeAuto = FALSE 时只做联锁与报警，不自动启停
   （手动模式由操作员点动，本规约不约束）。

扫描周期：20 ms；每次调用计为一个扫描周期。
初态：输出全 FALSE，Status = 16#0000；
LineRunLast、ResetBtnLast = FALSE，所有计数器 = 0。

约束：
K1 LineRun = FALSE 时两台电机必须为 FALSE。
K2 PartAtMerge = TRUE 时 MergeMotor 不得为 TRUE。
K3 连续堵料 2 s 内报警并停机，Status = 16#8C01；报警锁存到复位。
K4 复位需要 JamSensor = FALSE 且 ResetBtn 上升沿；
   复位后需重新 LineRun 上升沿。
K5 有料 3 s 切高速、无料 5 s 回落低速，中间保持档位。

完整形式化规约：
C1: G(!LineRun -> !MainMotor && !MergeMotor)
C4: G(PartAtMerge -> !MergeMotor)
C5: G(JamSensor && LineRun -> F[0,100] JamAlarm)
C6: G(JamAlarm && !(ResetBtn && !JamSensor) -> X(JamAlarm))
C7: G(PartOnMain && MainMotor && !SpeedHigh -> F[0,150] SpeedHigh)
C10: G[0,1](!MainMotor && !MergeMotor && !SpeedHigh &&
             !JamAlarm && Status == 16#0000)

待审语义冲突，不能声称同时满足原文与全部 LTL：
- C5 对单周期堵料也产生限时报警义务；原文要求连续 100 周期，
  信号提前消失时不应报警。本实现使用连续计数。
- C7 对单周期有料也产生限时升档义务，且未排除随后停机；
  原文要求主电机运行且连续有料 150 周期。本实现使用连续计数。
- C10 要求最初两个时刻输出全部为初态，与初始 LineRun=TRUE
  形成上升沿即启动冲突。本实现初始化为指定初态，但不新增启动延迟。
- C6 使用按钮电平而非上升沿，且跨下一状态的保持表达式与扫描内
  接受复位的时点可能不同。本实现按原文使用复位上升沿。
- 停线要求 Status=0000，与报警期间 Status=8C01 的无条件表述冲突。
  本实现停线时 Status=0000，但 JamAlarm 仍锁存。
- 接口没有手动点动命令。本实现手动模式不自动启动、不自动恢复
  汇流电机、不自动换档，仅保持已有命令并施加停线、报警及防撞联锁；
  不增加外部接口，也不声称实现了操作员点动。

未经过真实编译器验证；编译通过亦不能代替逐周期功能测试。
*)

(* 全模式均记录边沿；手动期间的边沿不会在返回自动时重放。 *)
LineRunRise := LineRun AND NOT LineRunLast;
ResetBtnRise := ResetBtn AND NOT ResetBtnLast;
ResetAccepted := ResetBtnRise AND NOT JamSensor;

(* 连续堵料计数：第 100 次连续 TRUE 调用置位，计数饱和。 *)
IF JamSensor THEN
    IF JamCount < UINT#100 THEN
        JamCount := JamCount + UINT#1;
    END_IF;
ELSE
    JamCount := UINT#0;
END_IF;

IF JamCount >= UINT#100 THEN
    JamAlarm := TRUE;
END_IF;

(* 有效复位优先于启动；同时出现的运行上升沿被消耗。 *)
IF ResetAccepted THEN
    JamAlarm := FALSE;
    Status := WORD#16#0000;
    MainMotor := FALSE;
    MergeMotor := FALSE;
    PartPresentCount := UINT#0;
    PartAbsentCount := UINT#0;
END_IF;

(* 停线与报警停机在自动、手动模式中均生效。 *)
IF NOT LineRun THEN
    MainMotor := FALSE;
    MergeMotor := FALSE;
    SpeedHigh := FALSE;
    Status := WORD#16#0000;
    PartPresentCount := UINT#0;
    PartAbsentCount := UINT#0;

ELSIF JamAlarm THEN
    MainMotor := FALSE;
    MergeMotor := FALSE;
    Status := WORD#16#8C01;
    PartPresentCount := UINT#0;
    PartAbsentCount := UINT#0;

ELSE
    Status := WORD#16#0000;

    IF ModeAuto AND NOT ResetAccepted THEN
        IF LineRunRise THEN
            MainMotor := TRUE;
        END_IF;

        MergeMotor := MainMotor AND NOT PartAtMerge;

        (* 高速计数须同时满足主电机运行与连续有料。 *)
        IF MainMotor AND PartOnMain THEN
            IF PartPresentCount < UINT#150 THEN
                PartPresentCount := PartPresentCount + UINT#1;
            END_IF;
        ELSE
            PartPresentCount := UINT#0;
        END_IF;

        (* 无料连续计数独立于主电机运行状态。 *)
        IF NOT PartOnMain THEN
            IF PartAbsentCount < UINT#250 THEN
                PartAbsentCount := PartAbsentCount + UINT#1;
            END_IF;
        ELSE
            PartAbsentCount := UINT#0;
        END_IF;

        IF PartPresentCount >= UINT#150 THEN
            SpeedHigh := TRUE;
        ELSIF PartAbsentCount >= UINT#250 THEN
            SpeedHigh := FALSE;
        END_IF;
    ELSE
        (* 手动或本扫描复位：不自动换档，不累计自动延时。 *)
        PartPresentCount := UINT#0;
        PartAbsentCount := UINT#0;
    END_IF;
END_IF;

(* 最终安全联锁：任何模式均不得绕过。 *)
IF PartAtMerge OR NOT MainMotor THEN
    MergeMotor := FALSE;
END_IF;

LineRunLast := LineRun;
ResetBtnLast := ResetBtn;

END_FUNCTION_BLOCK
